INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_GROUP_ORDER', '학원 단체 주문 문의', '길 건너 보습학원에서 원생 40명분 저녁 간식을 이번 주 금요일까지 맞춰 줄 수 있느냐고 물어 왔습니다. 단가를 조금 깎아 주면 앞으로도 자주 맡기겠다는 말도 덧붙였습니다.', '{"var":"quartersOperated","op":">=","value":2}'::jsonb, 0.7, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '정가로 받고 총동원해 맞추기', '{"base":0.6,"statBonus":[{"stat":"management","per10":0.04},{"stat":"cooking","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":2500000,"memo":"학원 단체 주문 매출"},{"type":"STAT","stat":"stamina","delta":-1}]'::jsonb, '[{"type":"CASH","amount":800000,"memo":"단체 주문 일부 환불 후 매출"},{"type":"STAT","stat":"service","delta":-2}]'::jsonb, '금요일 저녁, 40개 상자가 시간 맞춰 학원에 들어갔습니다. 원장님이 엄지를 들어 보였습니다.', '두 상자가 늦게 도착해 일부를 환불했습니다. 남은 건 피곤함과 약간의 매출입니다.' FROM turning_points WHERE code = 'MI_GROUP_ORDER';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '단가를 깎아 주고 단골 거래 노리기', '{"base":0.65,"statBonus":[{"stat":"network","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":1200000,"memo":"할인 단체 주문 매출"},{"type":"STAT","stat":"network","delta":2},{"type":"FLAG","flag":"MI_F_GROUP_ORDER","value":true}]'::jsonb, '[{"type":"CASH","amount":500000,"memo":"할인 단체 주문 매출"},{"type":"STAT","stat":"stamina","delta":-1},{"type":"FLAG","flag":"MI_F_GROUP_ORDER","value":true}]'::jsonb, '남는 건 적었지만 원장님이 명함을 챙겨 갔습니다. 다음에 또 연락하겠다고 합니다.', '할인까지 해 줬는데 배송이 빠듯해 진땀을 뺐습니다. 그래도 원장님 연락처는 남았습니다.' FROM turning_points WHERE code = 'MI_GROUP_ORDER';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '이번엔 정중히 거절', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":1},{"type":"STAT","stat":"network","delta":-1}]'::jsonb, '[]'::jsonb, '무리하지 않고 평소 손님에게 집중했습니다. 원장님은 조금 아쉬워하는 눈치였습니다.', '-' FROM turning_points WHERE code = 'MI_GROUP_ORDER';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_GROUP_REGULAR', '학원에서 온 정기 주문 제안', '지난번 단체 주문을 맡겼던 학원 원장님이 다시 연락해 왔습니다. 방학 특강 동안 매주 간식을 넣어 달라며, 대신 단가를 조금 더 맞춰 달라고 합니다.', '{"all":[{"var":"flag.MI_F_GROUP_ORDER","op":"==","value":true},{"var":"history.quartersSince.MI_GROUP_ORDER","op":"between","value":[2,6]}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 0, 1, 1, 80, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '조건 그대로 정기 납품 수락', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.06,"quarters":2,"label":"학원 정기 납품 매출 +6%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.01,"quarters":2,"label":"납품 할인 원가 +1%p"},{"type":"STAT","stat":"stamina","delta":-2},{"type":"FLAG","flag":"MI_F_GROUP_ORDER","value":false}]'::jsonb, '[]'::jsonb, '매주 화요일과 목요일, 학원 간식 상자가 고정 일정이 됐습니다. 바쁘지만 매출이 든든합니다.', '-' FROM turning_points WHERE code = 'MI_GROUP_REGULAR';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '단가는 지키며 협상하기', '{"base":0.5,"statBonus":[{"stat":"network","per10":0.05},{"stat":"management","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.08,"quarters":2,"label":"정기 납품 매출 +8%"},{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_GROUP_ORDER","value":false}]'::jsonb, '[{"type":"STAT","stat":"network","delta":-1},{"type":"FLAG","flag":"MI_F_GROUP_ORDER","value":false}]'::jsonb, '원장님이 웃으며 정가에 도장을 찍었습니다. 지난번 성의를 기억하고 있었습니다.', '원장님은 더 싼 곳을 알아보겠다며 전화를 끊었습니다. 협상은 여기까지였습니다.' FROM turning_points WHERE code = 'MI_GROUP_REGULAR';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '일손이 부족해 사양하기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":1},{"type":"FLAG","flag":"MI_F_GROUP_ORDER","value":false}]'::jsonb, '[]'::jsonb, '지금 인원으로는 무리라고 솔직히 말씀드렸습니다. 원장님도 사정을 이해해 주셨습니다.', '-' FROM turning_points WHERE code = 'MI_GROUP_REGULAR';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_STAFF_LATE', '또 늦은 아르바이트생', '아르바이트생이 이번 달에만 세 번째 지각했습니다. 사정을 들어 보니 집이 멀어 첫차를 놓치면 답이 없다고 합니다. 다른 직원들은 슬슬 눈치를 보고 있습니다.', '{"var":"staff","op":">=","value":1}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 6, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '따끔하게 주의 주기', '{"base":0.6,"statBonus":[{"stat":"management","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"STAT","stat":"management","delta":2}]'::jsonb, '[{"type":"STAT","stat":"service","delta":-1},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.97,"quarters":1,"label":"직원 사기 저하 방문객 -3%"}]'::jsonb, '다음 날부터 출근 시간이 칼같아졌습니다. 다른 직원들도 분위기를 읽었습니다.', '말이 너무 셌는지 한동안 가게 분위기가 싸늘했습니다. 손님도 그걸 느낀 듯합니다.' FROM turning_points WHERE code = 'MI_STAFF_LATE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '출근 시간을 30분 늦춰 주기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":-2},{"type":"STAT","stat":"service","delta":1}]'::jsonb, '[]'::jsonb, '오픈 준비는 사장님 몫이 됐지만, 지각은 사라지고 직원 표정이 밝아졌습니다.', '-' FROM turning_points WHERE code = 'MI_STAFF_LATE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '못 본 척 넘어가기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.96,"quarters":1,"label":"오픈 응대 공백 방문객 -4%"},{"type":"STAT","stat":"management","delta":-1}]'::jsonb, '[]'::jsonb, '오늘도 오픈 직후 10분은 사장님 혼자 뛰어다녔습니다. 기다리던 손님 몇은 그냥 돌아갔습니다.', '-' FROM turning_points WHERE code = 'MI_STAFF_LATE';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_BAD_REVIEW', '별점 하나짜리 리뷰', '"음식이 미지근했고 직원이 무심했다"는 별점 1점 리뷰가 올라왔습니다. 그날 주문 기록을 보니 손님 말이 반쯤은 맞는 것 같아 마음이 복잡합니다.', '{"var":"quartersOperated","op":">=","value":2}'::jsonb, 0.7, '[]'::jsonb, 0, 1, 6, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '사과 답글과 재방문 쿠폰', '{"base":0.65,"statBonus":[{"stat":"service","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"사과 쿠폰 비용"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.04,"quarters":1,"label":"성의 있는 답글 호감 +4%"}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"사과 쿠폰 비용"},{"type":"STAT","stat":"marketing","delta":-1}]'::jsonb, '정중한 답글에 다른 손님들이 "이 집 사장님 괜찮네"라는 댓글을 남겼습니다.', '쿠폰은 나갔지만 손님은 끝내 답이 없었습니다. 리뷰는 그대로 남아 있습니다.' FROM turning_points WHERE code = 'MI_BAD_REVIEW';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '사실관계를 조목조목 반박', '{"base":0.3,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"STAT","stat":"marketing","delta":2}]'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.94,"quarters":2,"label":"반박 답글 역풍 방문객 -6%"},{"type":"STAT","stat":"service","delta":-1}]'::jsonb, '차분한 해명 덕에 오해가 풀렸고, 리뷰 작성자가 별점을 3점으로 고쳤습니다.', '답글이 캡처되어 동네 게시판에 돌았습니다. "사장님이 손님이랑 싸운다"는 말이 붙었습니다.' FROM turning_points WHERE code = 'MI_BAD_REVIEW';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '대응하지 않고 넘기기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.97,"quarters":1,"label":"악성 리뷰 노출 방문객 -3%"}]'::jsonb, '[]'::jsonb, '리뷰는 금방 다른 글에 묻혔지만, 그사이 몇몇 손님은 발길을 돌렸을지도 모릅니다.', '-' FROM turning_points WHERE code = 'MI_BAD_REVIEW';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_SUPPLIER_HIKE', '식자재 납품가 인상 통보', '거래하던 식자재 업체가 다음 분기부터 납품가를 올리겠다는 문자를 보냈습니다. 인건비와 운송비가 올라 어쩔 수 없다는데, 계산기를 두드려 보니 꽤 아픕니다.', '{"var":"quartersOperated","op":">=","value":2}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '그대로 받아들이기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"납품가 인상 원가 +2%p"},{"type":"STAT","stat":"network","delta":1}]'::jsonb, '[]'::jsonb, '오래 거래한 정을 생각해 군말 없이 받아들였습니다. 업체 사장님이 고맙다며 덤을 챙겨 줍니다.', '-' FROM turning_points WHERE code = 'MI_SUPPLIER_HIKE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '새 거래처로 바꾸기', '{"base":0.55,"statBonus":[{"stat":"management","per10":0.04},{"stat":"network","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":-0.01,"quarters":2,"label":"새 거래처 원가 -1%p"},{"type":"FLAG","flag":"MI_F_NEW_SUPPLIER","value":true}]'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.01,"quarters":1,"label":"거래처 교체 혼선 원가 +1%p"},{"type":"STAT","stat":"cooking","delta":-1},{"type":"FLAG","flag":"MI_F_NEW_SUPPLIER","value":true}]'::jsonb, '발품을 판 끝에 더 싸고 물건도 괜찮은 업체를 찾았습니다.', '새 업체 재료가 들쭉날쭉해 첫 달은 버린 재료가 많았습니다.' FROM turning_points WHERE code = 'MI_SUPPLIER_HIKE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '메뉴 가격을 살짝 올리기', '{"base":0.5,"statBonus":[{"stat":"marketing","per10":0.04},{"stat":"cooking","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.03,"quarters":2,"label":"메뉴 가격 조정 매출 +3%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"납품가 인상 원가 +2%p"}]'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":2,"label":"가격 인상 반감 방문객 -5%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"납품가 인상 원가 +2%p"}]'::jsonb, '메뉴판 숫자가 바뀌었지만 손님들은 크게 개의치 않았습니다.', '"여기도 올랐네"라는 말이 들리더니 한동안 손님이 줄었습니다.' FROM turning_points WHERE code = 'MI_SUPPLIER_HIKE';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_SUPPLIER_CONTRACT', '새 거래처의 장기 계약 제안', '몇 달 전 바꾼 식자재 거래처에서 1년 장기 계약을 맺으면 단가를 더 내려 주겠다고 합니다. 다만 중간에 해지하면 위약금이 있고, 요즘 배송이 가끔 늦는 게 마음에 걸립니다.', '{"all":[{"var":"flag.MI_F_NEW_SUPPLIER","op":"==","value":true},{"var":"history.quartersSince.MI_SUPPLIER_HIKE","op":"between","value":[2,6]}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 0, 1, 1, 80, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '1년 장기 계약 체결', '{"base":0.6,"statBonus":[{"stat":"management","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":-0.02,"quarters":3,"label":"장기 계약 단가 원가 -2%p"},{"type":"FLAG","flag":"MI_F_NEW_SUPPLIER","value":false}]'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"배송 지연 대체 구매비"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":-0.01,"quarters":2,"label":"장기 계약 단가 원가 -1%p"},{"type":"FLAG","flag":"MI_F_NEW_SUPPLIER","value":false}]'::jsonb, '도장을 찍은 뒤로 배송도 제때 오고 단가도 내려갔습니다. 잘한 선택이었습니다.', '단가는 내려갔지만 배송 사고가 두 번 나서 급히 동네 마트를 뛰어다녔습니다.' FROM turning_points WHERE code = 'MI_SUPPLIER_CONTRACT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '지금처럼 건별 거래 유지', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"management","delta":1},{"type":"FLAG","flag":"MI_F_NEW_SUPPLIER","value":false}]'::jsonb, '[]'::jsonb, '묶이지 않는 쪽을 택했습니다. 단가는 그대로지만 언제든 다른 곳을 고를 수 있습니다.', '-' FROM turning_points WHERE code = 'MI_SUPPLIER_CONTRACT';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_RAINY_SEASON', '장마 예보', '다음 분기 내내 비 소식이 이어진다는 예보가 나왔습니다. 장마철엔 우산 든 손님이 줄고 집에서 시켜 먹는 손님이 늘기 마련입니다. 어떻게 대비할지 정해야 합니다.', '{"var":"quarterOfYear","op":"==","value":2}'::jsonb, 0.9, '[]'::jsonb, 0, 1, 3, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '포장·배달 할인 걸기', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"우천 포장 할인 비용"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.06,"quarters":1,"label":"우천 포장 주문 매출 +6%"}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"우천 포장 할인 비용"},{"type":"STAT","stat":"marketing","delta":1}]'::jsonb, '"비 오는 날 포장 10% 할인" 문구가 통했습니다. 비가 올수록 포장 주문이 늘었습니다.', '할인을 걸었지만 다들 집 근처 가게에서 해결했는지 반응이 미지근했습니다.' FROM turning_points WHERE code = 'MI_RAINY_SEASON';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '입구에 우산꽂이와 매트 깔기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"우천 대비 용품 구입"},{"type":"STAT","stat":"service","delta":1},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.98,"quarters":1,"label":"장마철 방문객 -2%"}]'::jsonb, '[]'::jsonb, '젖은 바닥 걱정 없는 가게라는 말이 돌았습니다. 그래도 비는 비입니다.', '-' FROM turning_points WHERE code = 'MI_RAINY_SEASON';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '평소대로 영업', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":1,"label":"장마철 방문객 -5%"}]'::jsonb, '[]'::jsonb, '비가 세차게 오는 날엔 가게 앞 골목이 텅 비었습니다.', '-' FROM turning_points WHERE code = 'MI_RAINY_SEASON';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_AIRCON_BREAK', '한여름 앞둔 에어컨 고장', '더위가 시작되려는데 매장 에어컨에서 더운 바람만 나옵니다. 기사님은 부품을 갈아도 되지만 연식이 있어 언제 또 멈출지 모른다고 합니다.', '{"all":[{"var":"quarterOfYear","op":"==","value":2},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.5, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '새 에어컨으로 교체', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-3000000,"memo":"에어컨 교체 비용"},{"type":"STAT","stat":"service","delta":1}]'::jsonb, '[]'::jsonb, '시원한 바람이 나오자 손님들이 자리를 오래 지켰습니다. 통장은 조금 서늘해졌습니다.', '-' FROM turning_points WHERE code = 'MI_AIRCON_BREAK';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '부품만 갈아서 버티기', '{"base":0.5,"statBonus":[{"stat":"management","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"에어컨 부품 수리비"}]'::jsonb, '[{"type":"CASH","amount":-1800000,"memo":"에어컨 재수리비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":1,"label":"더운 매장 방문객 -5%"}]'::jsonb, '수리한 에어컨이 한여름을 무사히 버텨 줬습니다.', '8월 첫 주에 에어컨이 다시 멈췄습니다. 결국 수리비가 두 번 들었습니다.' FROM turning_points WHERE code = 'MI_AIRCON_BREAK';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '선풍기와 냉수로 버티기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.92,"quarters":1,"label":"더운 매장 방문객 -8%"},{"type":"STAT","stat":"stamina","delta":-2}]'::jsonb, '[]'::jsonb, '선풍기 네 대가 쉬지 않고 돌았지만 손님들은 시원한 옆 가게로 향했습니다.', '-' FROM turning_points WHERE code = 'MI_AIRCON_BREAK';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_SUMMER_ICE_MENU', '여름 한정 빙수 메뉴', '날이 더워지자 단골들이 "여긴 빙수 안 해요?"라고 묻기 시작했습니다. 빙삭기를 들이면 여름 매출을 노려 볼 수 있지만, 실패하면 창고에 기계 하나가 늘어납니다.', '{"all":[{"var":"quarterOfYear","op":"==","value":2},{"var":"serviceCode","op":"in","value":["CS100005","CS100010"]}]}'::jsonb, 0.9, '[]'::jsonb, 0, 1, 3, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '빙삭기 들이고 빙수 출시', '{"base":0.55,"statBonus":[{"stat":"cooking","per10":0.04},{"stat":"marketing","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"빙삭기와 재료 준비"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.1,"quarters":1,"label":"여름 빙수 매출 +10%"}]'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"빙삭기와 재료 준비"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.02,"quarters":1,"label":"여름 빙수 매출 +2%"}]'::jsonb, '첫 주말부터 빙수 사진이 동네 단톡방에 돌았습니다. 여름 내내 빙삭기가 쉴 틈이 없었습니다.', '빙수는 그럭저럭 나갔지만 기계값을 뽑기엔 여름이 짧았습니다.' FROM turning_points WHERE code = 'MI_SUMMER_ICE_MENU';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '아이스 음료 메뉴만 늘리기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"아이스 메뉴 재료 준비"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.03,"quarters":1,"label":"아이스 메뉴 매출 +3%"}]'::jsonb, '[]'::jsonb, '큰 투자 없이 시원한 메뉴를 몇 가지 더했습니다. 무난한 여름이었습니다.', '-' FROM turning_points WHERE code = 'MI_SUMMER_ICE_MENU';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '기존 메뉴로 승부', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"cooking","delta":1}]'::jsonb, '[]'::jsonb, '유행을 좇지 않고 기본 메뉴의 맛을 다듬는 데 집중했습니다.', '-' FROM turning_points WHERE code = 'MI_SUMMER_ICE_MENU';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_NEIGHBOR_WORKS', '옆 가게 인테리어 공사', '옆 점포가 3주 동안 인테리어 공사를 한다고 합니다. 드릴 소리와 먼지 때문에 손님들이 문 앞에서 머뭇거립니다. 공사 팀장님은 미안하다며 연신 고개를 숙입니다.', '{"var":"quartersOperated","op":">=","value":2}'::jsonb, 0.5, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '영업 손실 보상을 요구', '{"base":0.45,"statBonus":[{"stat":"network","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":1500000,"memo":"공사 소음 보상금"}]'::jsonb, '[{"type":"STAT","stat":"network","delta":-2},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":1,"label":"공사 소음 방문객 -5%"}]'::jsonb, '새 가게 사장님이 순순히 보상금을 건넸습니다. 다만 첫인상은 조금 딱딱해졌습니다.', '보상은커녕 언성만 높아졌습니다. 공사는 그대로 3주를 꽉 채웠습니다.' FROM turning_points WHERE code = 'MI_NEIGHBOR_WORKS';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '공사 팀에 간식 돌리며 협조', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"공사 팀 간식비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.97,"quarters":1,"label":"공사 소음 방문객 -3%"},{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_NEIGHBOR_FRIEND","value":true}]'::jsonb, '[]'::jsonb, '간식을 받은 팀장님이 시끄러운 작업을 손님 적은 오후로 몰아 주었습니다.', '-' FROM turning_points WHERE code = 'MI_NEIGHBOR_WORKS';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '참고 버티기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.94,"quarters":1,"label":"공사 소음 방문객 -6%"}]'::jsonb, '[]'::jsonb, '3주가 3개월처럼 느껴졌습니다. 그래도 공사는 끝났습니다.', '-' FROM turning_points WHERE code = 'MI_NEIGHBOR_WORKS';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_NEIGHBOR_COLLAB', '옆 가게의 공동 이벤트 제안', '공사를 마치고 문을 연 옆 가게 사장님이 그때 협조해 줘서 고마웠다며 찾아왔습니다. 두 가게 영수증을 서로 할인해 주는 공동 쿠폰 이벤트를 해 보자고 합니다.', '{"all":[{"var":"flag.MI_F_NEIGHBOR_FRIEND","op":"==","value":true},{"var":"history.quartersSince.MI_NEIGHBOR_WORKS","op":"between","value":[2,6]}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 0, 1, 1, 80, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '공동 쿠폰 이벤트 함께하기', '{"base":0.65,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"공동 쿠폰 인쇄·할인 비용"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.08,"quarters":2,"label":"이웃 가게 공동 쿠폰 +8%"},{"type":"FLAG","flag":"MI_F_NEIGHBOR_FRIEND","value":false}]'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"공동 쿠폰 인쇄·할인 비용"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.02,"quarters":1,"label":"이웃 가게 공동 쿠폰 +2%"},{"type":"FLAG","flag":"MI_F_NEIGHBOR_FRIEND","value":false}]'::jsonb, '옆 가게 손님이 쿠폰을 들고 우리 가게로, 우리 손님이 옆 가게로 오갔습니다. 골목이 북적입니다.', '쿠폰은 생각보다 덜 돌았습니다. 그래도 이웃 사장님과는 한결 가까워졌습니다.' FROM turning_points WHERE code = 'MI_NEIGHBOR_COLLAB';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '마음만 받고 사양하기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_NEIGHBOR_FRIEND","value":false}]'::jsonb, '[]'::jsonb, '지금은 우리 가게 일만으로 벅차다고 말씀드렸습니다. 대신 커피 한 잔을 함께했습니다.', '-' FROM turning_points WHERE code = 'MI_NEIGHBOR_COLLAB';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_FLEA_MARKET', '주민센터 플리마켓 시식 부스', '주민센터 앞 공터에서 주말 플리마켓이 열린다며 상인회가 시식 부스 참가를 권했습니다. 동네 사람 얼굴을 익히기엔 좋지만, 주말 이틀을 꼬박 밖에서 보내야 합니다.', '{"all":[{"var":"quarterOfYear","op":"in","value":[1,3]},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '부스 내고 시식 행사', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.04},{"stat":"stamina","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"부스 참가비와 시식 재료"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.06,"quarters":2,"label":"플리마켓 입소문 방문객 +6%"},{"type":"STAT","stat":"network","delta":1}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"부스 참가비와 시식 재료"},{"type":"STAT","stat":"stamina","delta":-2}]'::jsonb, '시식 접시가 순식간에 비었습니다. 다음 주부터 "플리마켓에서 먹어 봤다"는 손님이 찾아옵니다.', '하필 그 주말에 찬바람이 불어 사람이 적었습니다. 남은 시식 재료는 직원 간식이 됐습니다.' FROM turning_points WHERE code = 'MI_FLEA_MARKET';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '할인 쿠폰만 기부하기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"플리마켓 경품 쿠폰"},{"type":"STAT","stat":"network","delta":2}]'::jsonb, '[]'::jsonb, '경품 추첨함에 우리 가게 쿠폰이 들어갔습니다. 상인회장님이 고맙다고 전화를 주셨습니다.', '-' FROM turning_points WHERE code = 'MI_FLEA_MARKET';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '주말엔 가게를 지키기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":1}]'::jsonb, '[]'::jsonb, '평소처럼 가게를 지켰습니다. 플리마켓 소식은 다음 주 단골에게 전해 들었습니다.', '-' FROM turning_points WHERE code = 'MI_FLEA_MARKET';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_OFFICE_DINNER', '근처 사무실의 회식 문의', '근처 사무실 팀장님이 다음 달 회식 장소로 우리 가게를 찍었습니다. 스무 명이 한꺼번에 오고, 2차 없이 늦게까지 자리를 지키고 싶다며 마감 시간을 넘겨 달라고 합니다.', '{"all":[{"var":"serviceCode","op":"in","value":["CS100001","CS100002","CS100003","CS100007","CS100009"]},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '마감 연장하고 단체석 준비', '{"base":0.7,"statBonus":[{"stat":"stamina","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":2000000,"memo":"단체 회식 매출"},{"type":"STAT","stat":"stamina","delta":-2},{"type":"STAT","stat":"network","delta":1}]'::jsonb, '[{"type":"CASH","amount":1000000,"memo":"단체 회식 매출"},{"type":"STAT","stat":"stamina","delta":-3},{"type":"STAT","stat":"service","delta":-1}]'::jsonb, '밤 열두 시까지 건배 소리가 이어졌습니다. 팀장님이 다음 회식도 여기라고 못을 박았습니다.', '새벽까지 이어진 회식에 녹초가 됐습니다. 다음 날 오픈은 반쯤 감은 눈으로 했습니다.' FROM turning_points WHERE code = 'MI_OFFICE_DINNER';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '회식 전용 세트 메뉴 제안', '{"base":0.55,"statBonus":[{"stat":"cooking","per10":0.04},{"stat":"management","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":2500000,"memo":"회식 세트 매출"},{"type":"STAT","stat":"cooking","delta":1}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"세트 재료 남음"}]'::jsonb, '세트 메뉴 덕에 주방이 덜 바빴고 객단가는 올랐습니다. 깔끔한 한 판이었습니다.', '세트가 입맛에 안 맞았는지 단품 추가 주문이 쏟아졌고, 준비한 재료가 남았습니다.' FROM turning_points WHERE code = 'MI_OFFICE_DINNER';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '마감 시간은 지키겠다고 안내', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":800000,"memo":"단체 회식 매출"},{"type":"STAT","stat":"stamina","delta":1}]'::jsonb, '[]'::jsonb, '정해진 시간에 회식이 끝났습니다. 팀장님은 2차를 다른 데서 하겠다며 웃었습니다.', '-' FROM turning_points WHERE code = 'MI_OFFICE_DINNER';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_RIDER_COMPLAINT', '라이더들의 픽업 대기 불만', '배달 라이더들 사이에서 우리 가게는 픽업 대기가 길다는 말이 돈다고 합니다. 콜을 일부러 피하는 라이더가 늘면 배달이 늦어지고 리뷰에도 그대로 남습니다.', '{"any":[{"var":"flag.DELIVERY_ENABLED","op":"==","value":true},{"var":"serviceCode","op":"in","value":["CS100002","CS100006","CS100007","CS100008"]}]}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 6, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '출입구 옆에 픽업대 따로 만들기', '{"base":0.7,"statBonus":[{"stat":"management","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"픽업대 설치비"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.04,"quarters":2,"label":"배달 회전 개선 매출 +4%"}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"픽업대 설치비"},{"type":"STAT","stat":"management","delta":1}]'::jsonb, '라이더들이 들어오자마자 봉투를 들고 나갑니다. 배달 시간이 눈에 띄게 줄었습니다.', '픽업대는 생겼지만 주방 속도가 그대로라 대기 시간은 크게 줄지 않았습니다.' FROM turning_points WHERE code = 'MI_RIDER_COMPLAINT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '대기 라이더에게 음료 서비스', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"라이더 음료 서비스"},{"type":"STAT","stat":"network","delta":2}]'::jsonb, '[]'::jsonb, '"여긴 기다려도 음료는 준다"는 말이 라이더 단톡방에 돌았습니다.', '-' FROM turning_points WHERE code = 'MI_RIDER_COMPLAINT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '지금 방식 유지', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":0.96,"quarters":1,"label":"배달 지연 매출 -4%"}]'::jsonb, '[]'::jsonb, '배달 시간이 길어졌다는 리뷰가 몇 개 달렸습니다.', '-' FROM turning_points WHERE code = 'MI_RIDER_COMPLAINT';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_SNS_TREND', 'SNS에서 유행하는 메뉴', '요즘 SNS에 단면이 보이게 자른 크림 디저트 사진이 유행입니다. 단골 학생이 "사장님네도 하나 만들어 보세요"라며 휴대폰 화면을 내밉니다. 유행은 빨리 오고 빨리 갑니다.', '{"var":"quartersOperated","op":">=","value":2}'::jsonb, 0.6, '[{"stat":"marketing","per10":0.05}]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '유행 따라 한정 메뉴 출시', '{"base":0.5,"statBonus":[{"stat":"cooking","per10":0.04},{"stat":"marketing","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"한정 메뉴 개발·재료비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.1,"quarters":2,"label":"유행 메뉴 방문객 +10%"},{"type":"STAT","stat":"marketing","delta":2},{"type":"FLAG","flag":"MI_F_TREND_MENU","value":true}]'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"한정 메뉴 개발·재료비"},{"type":"STAT","stat":"cooking","delta":-1},{"type":"FLAG","flag":"MI_F_TREND_MENU","value":true}]'::jsonb, '사진 찍으러 온 손님들로 주말 줄이 생겼습니다. 단골 학생이 자기 덕이라며 뿌듯해합니다.', '모양을 내는 데 실패해 "실물이 다르다"는 후기가 붙었습니다.' FROM turning_points WHERE code = 'MI_SNS_TREND';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '기존 메뉴 사진만 새로 찍기', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"메뉴 사진 촬영비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.04,"quarters":1,"label":"새 메뉴 사진 방문객 +4%"}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"메뉴 사진 촬영비"}]'::jsonb, '조명만 바꿨는데 같은 메뉴가 훨씬 맛있어 보입니다. 사진을 보고 왔다는 손님이 생겼습니다.', '사진은 예쁘게 나왔지만 유행 메뉴만큼 눈길을 끌진 못했습니다.' FROM turning_points WHERE code = 'MI_SNS_TREND';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '유행은 지나간다며 패스', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"cooking","delta":1}]'::jsonb, '[]'::jsonb, '우리 가게다운 메뉴에 집중하기로 했습니다. 단골 학생은 조금 시무룩해졌습니다.', '-' FROM turning_points WHERE code = 'MI_SNS_TREND';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_TREND_FADE', '유행이 식은 한정 메뉴', '몇 달 전 들인 유행 메뉴를 찾는 손님이 눈에 띄게 줄었습니다. 전용 재료가 냉장고 한 칸을 차지하고 있는데, 이참에 정리할지 우리 가게 메뉴로 다듬어 남길지 정해야 합니다.', '{"all":[{"var":"flag.MI_F_TREND_MENU","op":"==","value":true},{"var":"history.quartersSince.MI_SNS_TREND","op":"between","value":[2,6]}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 0, 1, 1, 80, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '우리 식으로 다듬어 정식 메뉴로', '{"base":0.45,"statBonus":[{"stat":"cooking","per10":0.06}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.05,"quarters":3,"label":"정식 메뉴 편입 매출 +5%"},{"type":"STAT","stat":"cooking","delta":2},{"type":"FLAG","flag":"MI_F_TREND_MENU","value":false}]'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"남는 전용 재료 원가 +2%p"},{"type":"FLAG","flag":"MI_F_TREND_MENU","value":false}]'::jsonb, '유행 대신 맛으로 찾는 손님이 생겼습니다. 이제 이 메뉴는 그냥 우리 가게 메뉴입니다.', '고쳐 봤지만 반응이 없었습니다. 전용 재료만 계속 남습니다.' FROM turning_points WHERE code = 'MI_TREND_FADE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '깔끔하게 단종하기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"전용 재료 폐기"},{"type":"STAT","stat":"management","delta":1},{"type":"FLAG","flag":"MI_F_TREND_MENU","value":false}]'::jsonb, '[]'::jsonb, '메뉴판에서 한 줄을 지웠습니다. 냉장고도 마음도 한결 가벼워졌습니다.', '-' FROM turning_points WHERE code = 'MI_TREND_FADE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '떨이 할인으로 재고 털기', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":800000,"memo":"한정 메뉴 떨이 매출"},{"type":"FLAG","flag":"MI_F_TREND_MENU","value":false}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"팔리지 않은 재료 폐기"},{"type":"FLAG","flag":"MI_F_TREND_MENU","value":false}]'::jsonb, '"마지막 기회" 문구에 아쉬운 손님들이 몰려 재고가 금방 동났습니다.', '떨이에도 반응이 없어 결국 재료를 버렸습니다.' FROM turning_points WHERE code = 'MI_TREND_FADE';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_LOST_WATCH', '의자 밑에서 주운 손목시계', '마감 청소를 하다 의자 밑에서 묵직한 손목시계를 주웠습니다. 꽤 비싸 보이는데 연락처는 없습니다. CCTV를 돌려 보니 저녁 무렵 혼자 온 손님이 앉았던 자리입니다.', '{"var":"quartersOperated","op":">=","value":2}'::jsonb, 0.4, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '가게 문 앞에 습득 공지 붙이기', '{"base":0.7,"statBonus":[{"stat":"service","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"STAT","stat":"service","delta":1},{"type":"FLAG","flag":"MI_F_LOST_WATCH","value":true}]'::jsonb, '[{"type":"STAT","stat":"stamina","delta":-1},{"type":"FLAG","flag":"MI_F_LOST_WATCH","value":true}]'::jsonb, '"시계 주인을 찾습니다" 종이를 붙였습니다. 시계는 카운터 금고에 고이 넣어 두었습니다.', '공지를 보고 "제 거 같은데요"라며 우기는 사람과 한참 실랑이를 했습니다. 시계는 일단 보관합니다.' FROM turning_points WHERE code = 'MI_LOST_WATCH';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '가까운 지구대에 맡기기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":-1},{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_LOST_WATCH","value":true}]'::jsonb, '[]'::jsonb, '쉬는 시간에 지구대에 들러 습득물 신고를 했습니다. 경찰관이 연락처를 받아 갔습니다.', '-' FROM turning_points WHERE code = 'MI_LOST_WATCH';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '동네 단톡방에 수소문하기', '{"base":0.5,"statBonus":[{"stat":"network","per10":0.06}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"STAT","stat":"network","delta":2},{"type":"FLAG","flag":"MI_F_LOST_WATCH","value":true}]'::jsonb, '[{"type":"STAT","stat":"marketing","delta":-1},{"type":"FLAG","flag":"MI_F_LOST_WATCH","value":true}]'::jsonb, '단톡방에 올리자마자 "우리 동네 부동산 사장님 것 같다"는 답이 달렸습니다.', '"그거 제 거예요"라는 사람이 셋이나 나타나 한바탕 소동이 났습니다. 시계는 일단 보관합니다.' FROM turning_points WHERE code = 'MI_LOST_WATCH';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_WATCH_OWNER', '시계 주인이 찾아왔다', '얼마 전 맡아 두었던 손목시계의 주인이 찾아왔습니다. 길 건너 부동산을 하는 사장님인데, 돌아가신 아버지 유품이라며 꼭 사례를 하고 싶다고 합니다.', '{"all":[{"var":"flag.MI_F_LOST_WATCH","op":"==","value":true},{"var":"history.quartersSince.MI_LOST_WATCH","op":"between","value":[2,6]}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 0, 1, 1, 80, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '사례금을 감사히 받기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":1000000,"memo":"분실물 사례금"},{"type":"FLAG","flag":"MI_F_LOST_WATCH","value":false}]'::jsonb, '[]'::jsonb, '사장님이 봉투를 건네며 몇 번이고 고개를 숙였습니다.', '-' FROM turning_points WHERE code = 'MI_WATCH_OWNER';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '사양하고 손님 소개를 부탁', '{"base":0.6,"statBonus":[{"stat":"network","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.06,"quarters":2,"label":"부동산 사장님 소개 방문객 +6%"},{"type":"STAT","stat":"network","delta":2},{"type":"FLAG","flag":"MI_F_LOST_WATCH","value":false}]'::jsonb, '[{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_LOST_WATCH","value":false}]'::jsonb, '사장님이 집 보러 오는 손님마다 우리 가게를 맛집으로 소개해 주고 있습니다.', '사장님은 고맙다며 가끔 들르지만, 소개 손님까지는 이어지지 않았습니다.' FROM turning_points WHERE code = 'MI_WATCH_OWNER';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_EXAM_SHIFT', '아르바이트생의 시험 기간', '대학생 아르바이트생이 다음 달 시험 기간이라 2주만 근무를 빼 달라고 합니다. 성실한 친구라 붙잡고 싶은데, 하필 그 2주가 손님 많은 시기와 겹칩니다.', '{"all":[{"var":"staff","op":">=","value":1},{"var":"quarterOfYear","op":"in","value":[1,3]}]}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '흔쾌히 보내고 직접 메우기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":-3},{"type":"STAT","stat":"service","delta":1},{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '2주 동안 사장님이 1인 2역을 했습니다. 시험을 마친 아르바이트생이 커피를 사 들고 왔습니다.', '-' FROM turning_points WHERE code = 'MI_EXAM_SHIFT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '단기 대타 구하기', '{"base":0.6,"statBonus":[{"stat":"management","per10":0.04},{"stat":"network","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"단기 대타 인건비"}]'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"단기 대타 인건비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.97,"quarters":1,"label":"대타 응대 미숙 방문객 -3%"}]'::jsonb, '아르바이트생 친구가 대타로 와서 손발이 척척 맞았습니다.', '대타가 메뉴를 헷갈려 주문 실수가 잦았습니다.' FROM turning_points WHERE code = 'MI_EXAM_SHIFT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '시험 끝나면 보너스 줄 테니 남아 달라고 부탁', '{"base":0.4,"statBonus":[{"stat":"network","per10":0.05},{"stat":"service","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"시험 기간 근무 보너스"},{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"시험 기간 근무 보너스"},{"type":"STAT","stat":"service","delta":-2}]'::jsonb, '아르바이트생이 근무와 공부를 오가며 버텨 줬습니다. 보너스 봉투에 고맙다고 적었습니다.', '마지못해 남은 아르바이트생의 표정이 내내 어두웠고, 손님 응대도 건성이었습니다.' FROM turning_points WHERE code = 'MI_EXAM_SHIFT';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_LANDLORD_REPAIR', '건물 누수 공사비 분담 요청', '건물 외벽에서 물이 새 공사를 한다며 건물주가 공사비 일부를 나눠 내 달라고 합니다. 계약서를 다시 읽어 보니 누구 부담인지 애매하게 적혀 있습니다.', '{"var":"quartersOperated","op":">=","value":3}'::jsonb, 0.5, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '요청대로 분담하기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"건물 누수 공사비 분담"},{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_LANDLORD_GOODWILL","value":true}]'::jsonb, '[]'::jsonb, '군말 없이 공사비를 보냈습니다. 건물주가 "요즘 이런 세입자 드물다"며 웃었습니다.', '-' FROM turning_points WHERE code = 'MI_LANDLORD_REPAIR';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '계약서를 근거로 거절', '{"base":0.55,"statBonus":[{"stat":"management","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"공사비 일부 부담"},{"type":"STAT","stat":"network","delta":-2}]'::jsonb, '계약서 조항을 짚어 드렸더니 건물주가 수긍하고 전액 부담하기로 했습니다.', '말다툼 끝에 결국 일부를 내게 됐고, 건물주와 사이도 서먹해졌습니다.' FROM turning_points WHERE code = 'MI_LANDLORD_REPAIR';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '반반씩 나누자고 제안', '{"base":0.65,"statBonus":[{"stat":"network","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"건물 누수 공사비 절반 분담"}]'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"건물 누수 공사비 분담"}]'::jsonb, '반반으로 깔끔하게 정리됐습니다. 서로 얼굴 붉힐 일 없이 끝났습니다.', '건물주가 절충안을 거절해 결국 요청한 금액을 그대로 냈습니다.' FROM turning_points WHERE code = 'MI_LANDLORD_REPAIR';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_LANDLORD_THANKS', '건물주의 뜻밖의 제안', '지난번 누수 공사 때 선뜻 돈을 보탠 일을 건물주가 기억하고 있었습니다. 계약을 1년 더 연장해 주면 당분간 월세를 조금 깎아 주겠다는 제안입니다.', '{"all":[{"var":"flag.MI_F_LANDLORD_GOODWILL","op":"==","value":true},{"var":"history.quartersSince.MI_LANDLORD_REPAIR","op":"between","value":[2,6]}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 0, 1, 1, 80, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '계약 연장하고 월세 인하 받기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"rent","mode":"ADD","value":-500000,"quarters":3,"label":"건물주 배려 임대료 -50만 원"},{"type":"FLAG","flag":"MI_F_LANDLORD_GOODWILL","value":false}]'::jsonb, '[]'::jsonb, '도장을 찍고 나오는 길, 건물주가 귤 한 봉지를 쥐여 주었습니다.', '-' FROM turning_points WHERE code = 'MI_LANDLORD_THANKS';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '연장 없이 인하만 부탁해 보기', '{"base":0.45,"statBonus":[{"stat":"network","per10":0.06}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"rent","mode":"ADD","value":-300000,"quarters":2,"label":"임대료 -30만 원"},{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_LANDLORD_GOODWILL","value":false}]'::jsonb, '[{"type":"STAT","stat":"network","delta":-1},{"type":"FLAG","flag":"MI_F_LANDLORD_GOODWILL","value":false}]'::jsonb, '건물주가 껄껄 웃으며 "장사 잘하라"고 조건 없이 깎아 주었습니다.', '건물주는 연장이 안 되면 곤란하다며 이야기를 접었습니다.' FROM turning_points WHERE code = 'MI_LANDLORD_THANKS';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_LOCAL_VOUCHER', '지역 상품권 가맹점 모집', '구청에서 지역 상품권 가맹점을 모집한다는 안내문이 왔습니다. 상품권 손님이 늘어날 수 있지만 수수료가 붙고, 단말기 설정과 정산 확인도 사장님 몫입니다.', '{"var":"quartersOperated","op":">=","value":2}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '가맹 신청하기', '{"base":0.7,"statBonus":[{"stat":"management","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.05,"quarters":3,"label":"지역 상품권 손님 +5%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.01,"quarters":3,"label":"상품권 수수료 원가 +1%p"}]'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.01,"quarters":2,"label":"상품권 수수료 원가 +1%p"},{"type":"STAT","stat":"stamina","delta":-1}]'::jsonb, '문에 가맹점 스티커를 붙이자 상품권을 내미는 손님이 꾸준히 늘었습니다.', '정산 오류를 바로잡느라 한참 씨름했습니다. 손님 증가는 기대만 못했습니다.' FROM turning_points WHERE code = 'MI_LOCAL_VOUCHER';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '지금은 보류', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '수수료와 정산 부담을 생각해 이번엔 넘기기로 했습니다.', '-' FROM turning_points WHERE code = 'MI_LOCAL_VOUCHER';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_STUDENT_DISCOUNT', '학생회의 할인 요청', '근처 고등학교 학생회 임원 두 명이 손글씨 요청서를 들고 찾아왔습니다. 학생증을 보여 주면 10% 깎아 달라는 내용인데, 받아 주면 학교에 홍보해 주겠다고 합니다.', '{"all":[{"var":"serviceCode","op":"in","value":["CS100005","CS100006","CS100007","CS100008","CS100010"]},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '학생 10% 할인 수락', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.08,"quarters":2,"label":"학생 할인 방문객 +8%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"학생 할인 원가 +2%p"}]'::jsonb, '[]'::jsonb, '하교 시간마다 교복 입은 손님이 우르르 몰려옵니다. 가게가 시끌벅적해졌습니다.', '-' FROM turning_points WHERE code = 'MI_STUDENT_DISCOUNT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '할인 대신 음료 하나 서비스', '{"base":0.6,"statBonus":[{"stat":"service","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"학생 음료 서비스"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"학생 서비스 방문객 +5%"}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"학생 음료 서비스"},{"type":"STAT","stat":"marketing","delta":-1}]'::jsonb, '학생들이 "음료 주는 집"이라며 친구들을 데려옵니다.', '학생회는 할인이 아니면 홍보는 어렵다며 시큰둥하게 돌아갔습니다.' FROM turning_points WHERE code = 'MI_STUDENT_DISCOUNT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '정중히 거절', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"marketing","delta":-1},{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '가격 정책은 지키기로 했습니다. 학생들은 꾸벅 인사하고 돌아갔습니다.', '-' FROM turning_points WHERE code = 'MI_STUDENT_DISCOUNT';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_BEAN_PITCH', '원두 납품업체의 새 블렌드', '원두 납품업체 영업 사원이 새 블렌드 샘플을 들고 왔습니다. 마셔 보니 확실히 향이 좋은데 단가가 지금보다 1할쯤 비쌉니다. 단골들이 차이를 알아챌지가 관건입니다.', '{"var":"serviceCode","op":"==","value":"CS100010"}'::jsonb, 0.7, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '새 원두로 전면 교체', '{"base":0.55,"statBonus":[{"stat":"cooking","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.07,"quarters":3,"label":"원두 교체 매출 +7%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":3,"label":"원두 단가 원가 +2%p"}]'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"원두 단가 원가 +2%p"},{"type":"STAT","stat":"cooking","delta":1}]'::jsonb, '"커피 맛이 달라졌다"는 칭찬이 이어지고 원두를 사 가는 손님까지 생겼습니다.', '원가만 오르고 손님들은 맛 차이를 잘 모르는 눈치였습니다.' FROM turning_points WHERE code = 'MI_BEAN_PITCH';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '시즌 한정 메뉴로만 써 보기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"시즌 원두 소량 구매"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.02,"quarters":1,"label":"시즌 원두 메뉴 매출 +2%"}]'::jsonb, '[]'::jsonb, '칠판에 "이번 시즌 원두"를 적어 두었습니다. 찾는 손님이 꽤 있습니다.', '-' FROM turning_points WHERE code = 'MI_BEAN_PITCH';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '지금 원두 유지', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '익숙한 맛을 지키기로 했습니다. 영업 사원은 다음 시즌에 또 오겠다고 했습니다.', '-' FROM turning_points WHERE code = 'MI_BEAN_PITCH';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_CRAFT_BEER_TAP', '수제 맥주 탭 설치 제안', '동네 양조장 영업 사원이 생맥주 탭 하나를 무상으로 설치해 주겠다고 합니다. 대신 6개월 동안 매달 최소 구매량을 채워야 합니다. 손님 반응이 갈릴 수 있습니다.', '{"var":"serviceCode","op":"in","value":["CS100007","CS100009"]}'::jsonb, 0.7, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '탭 설치하고 대표 메뉴로 밀기', '{"base":0.55,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.07,"quarters":3,"label":"수제 맥주 매출 +7%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.01,"quarters":3,"label":"수제 맥주 원가 +1%p"}]'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.03,"quarters":2,"label":"남는 맥주 원가 +3%p"}]'::jsonb, '"여기만 있는 맥주"를 찾아 일부러 오는 손님이 생겼습니다.', '최소 구매량을 채우느라 남는 맥주가 쌓였습니다. 직원 회식이 잦아졌습니다.' FROM turning_points WHERE code = 'MI_CRAFT_BEER_TAP';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '주말 시음회만 열어 보기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"수제 맥주 시음회 비용"},{"type":"STAT","stat":"marketing","delta":1}]'::jsonb, '[]'::jsonb, '시음회는 즐거웠고 손님 반응도 살펴봤습니다. 설치 여부는 천천히 정하기로 했습니다.', '-' FROM turning_points WHERE code = 'MI_CRAFT_BEER_TAP';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '기존 맥주로 충분', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '익숙한 맥주가 제일 잘 팔린다는 걸 믿기로 했습니다.', '-' FROM turning_points WHERE code = 'MI_CRAFT_BEER_TAP';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_POINT_CARD', '단골 적립 제도 도입', '단골손님이 "여긴 도장 안 찍어 줘요?"라고 묻습니다. 종이 쿠폰은 싸지만 잃어버리기 쉽고, 적립 단말기는 비싸지만 손님 방문 기록이 남습니다.', '{"var":"quartersOperated","op":">=","value":3}'::jsonb, 0.5, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '종이 도장 쿠폰 만들기', '{"base":0.7,"statBonus":[{"stat":"service","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"도장 쿠폰 인쇄비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.04,"quarters":2,"label":"도장 쿠폰 재방문 +4%"}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"도장 쿠폰 인쇄비"}]'::jsonb, '도장 열 개를 채우려는 손님들이 부지런히 찾아옵니다.', '쿠폰을 받아 가고는 다들 지갑 어딘가에 묻어 둔 모양입니다.' FROM turning_points WHERE code = 'MI_POINT_CARD';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '적립 단말기 들이기', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-2000000,"memo":"적립 단말기 설치비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.07,"quarters":3,"label":"적립 단골 재방문 +7%"},{"type":"FLAG","flag":"MI_F_POINT_APP","value":true}]'::jsonb, '[{"type":"CASH","amount":-2000000,"memo":"적립 단말기 설치비"},{"type":"STAT","stat":"stamina","delta":-1},{"type":"FLAG","flag":"MI_F_POINT_APP","value":true}]'::jsonb, '전화번호 뒷자리만 누르면 쌓이는 적립에 손님들이 금세 익숙해졌습니다.', '단말기 사용법을 묻는 손님 때문에 계산대 줄이 길어졌습니다. 적립률은 아직 낮습니다.' FROM turning_points WHERE code = 'MI_POINT_CARD';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '적립 없이 맛으로 승부', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"cooking","delta":1}]'::jsonb, '[]'::jsonb, '"맛있으면 또 온다"는 원칙을 지키기로 했습니다.', '-' FROM turning_points WHERE code = 'MI_POINT_CARD';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_POINT_INSIGHT', '적립 기록이 알려 준 빈 시간', '적립 단말기에 몇 달 치 기록이 쌓였습니다. 들여다보니 화요일 오후 손님이 유독 적고, 한 달 넘게 안 온 단골도 서른 명이 넘습니다. 숫자가 말을 걸어옵니다.', '{"all":[{"var":"flag.MI_F_POINT_APP","op":"==","value":true},{"var":"history.quartersSince.MI_POINT_CARD","op":"between","value":[2,6]}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 0, 1, 1, 80, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '화요일 오후 두 배 적립', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"두 배 적립 비용"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"한산한 시간 매출 +5%"},{"type":"FLAG","flag":"MI_F_POINT_APP","value":false}]'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"두 배 적립 비용"},{"type":"FLAG","flag":"MI_F_POINT_APP","value":false}]'::jsonb, '조용하던 화요일 오후가 제법 북적이기 시작했습니다.', '두 배 적립에도 화요일은 여전히 조용했습니다. 원래 그런 날인가 봅니다.' FROM turning_points WHERE code = 'MI_POINT_INSIGHT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '뜸한 단골에게 안부 문자', '{"base":0.55,"statBonus":[{"stat":"service","per10":0.04},{"stat":"network","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"문자 발송비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"단골 복귀 방문객 +5%"},{"type":"FLAG","flag":"MI_F_POINT_APP","value":false}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"문자 발송비"},{"type":"STAT","stat":"marketing","delta":-1},{"type":"FLAG","flag":"MI_F_POINT_APP","value":false}]'::jsonb, '"사장님 문자 받고 생각나서 왔어요"라는 손님이 하나둘 돌아왔습니다.', '광고 문자로 보였는지 수신 거부만 몇 건 들어왔습니다.' FROM turning_points WHERE code = 'MI_POINT_INSIGHT';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_LUNAR_HOLIDAY', '설 연휴 영업 고민', '다가오는 설 연휴에 문을 열지 고민입니다. 연휴엔 문 연 가게를 찾는 손님이 몰리기도 하지만, 직원들은 고향에 가고 싶어 하고 사장님 몸도 쉬고 싶다고 합니다.', '{"var":"quarterOfYear","op":"==","value":4}'::jsonb, 0.9, '[]'::jsonb, 0, 1, 3, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '연휴 내내 영업', '{"base":0.6,"statBonus":[{"stat":"stamina","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.06,"quarters":1,"label":"연휴 영업 매출 +6%"},{"type":"STAT","stat":"stamina","delta":-3}]'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.02,"quarters":1,"label":"연휴 영업 매출 +2%"},{"type":"STAT","stat":"stamina","delta":-3},{"type":"STAT","stat":"service","delta":-1}]'::jsonb, '연휴에 문을 연 가게가 드물어 손님이 줄을 섰습니다.', '생각보다 다들 고향에 가 버려 골목이 한산했습니다. 몸만 고단했습니다.' FROM turning_points WHERE code = 'MI_LUNAR_HOLIDAY';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '당일만 쉬고 연휴 수당 주기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"연휴 근무 수당"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.03,"quarters":1,"label":"연휴 영업 매출 +3%"}]'::jsonb, '[]'::jsonb, '설 당일 하루만 쉬었습니다. 수당을 받은 직원들이 기분 좋게 일했습니다.', '-' FROM turning_points WHERE code = 'MI_LUNAR_HOLIDAY';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '연휴 동안 푹 쉬기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":3},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":0.96,"quarters":1,"label":"연휴 휴무 매출 -4%"}]'::jsonb, '[]'::jsonb, '오랜만에 늦잠을 잤습니다. 문 닫은 사이 손님 몇은 다른 가게로 갔겠지요.', '-' FROM turning_points WHERE code = 'MI_LUNAR_HOLIDAY';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_CHUSEOK_GIFT', '추석 선물 세트 준비', '추석을 앞두고 "선물용으로 포장돼요?"라는 문의가 늘었습니다. 선물 세트를 꾸리면 명절 대목을 노릴 수 있지만, 포장재를 미리 사 두면 남을 위험도 있습니다.', '{"all":[{"var":"quarterOfYear","op":"==","value":2},{"var":"serviceCode","op":"in","value":["CS100001","CS100005","CS100010"]}]}'::jsonb, 0.9, '[]'::jsonb, 0, 1, 3, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '선물 세트 본격 출시', '{"base":0.55,"statBonus":[{"stat":"marketing","per10":0.04},{"stat":"cooking","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":2500000,"memo":"추석 선물 세트 순이익"}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"남은 포장재와 재료"}]'::jsonb, '근처 회사에서 직원 선물로 서른 세트를 주문했습니다. 명절 대목을 제대로 누렸습니다.', '세트를 넉넉히 준비했는데 절반이 남았습니다. 포장 상자가 창고를 차지합니다.' FROM turning_points WHERE code = 'MI_CHUSEOK_GIFT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '주문받은 만큼만 소량 포장', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":800000,"memo":"추석 소량 포장 순이익"},{"type":"STAT","stat":"stamina","delta":-1}]'::jsonb, '[]'::jsonb, '남는 것 없이 주문받은 만큼만 정성껏 포장했습니다.', '-' FROM turning_points WHERE code = 'MI_CHUSEOK_GIFT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '명절 포장은 하지 않기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":1}]'::jsonb, '[]'::jsonb, '평소대로 장사했습니다. 선물 문의 손님에겐 정중히 양해를 구했습니다.', '-' FROM turning_points WHERE code = 'MI_CHUSEOK_GIFT';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_DONATION_ASK', '아동센터의 연말 후원 부탁', '동네 지역아동센터 선생님이 연말 행사에 아이들 먹을 음식을 후원해 줄 수 있느냐고 조심스럽게 물었습니다. 형편이 넉넉하진 않지만 거절하기도 쉽지 않습니다.', '{"all":[{"var":"quarterOfYear","op":"==","value":3},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '흔쾌히 음식 후원', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"아동센터 음식 후원"},{"type":"STAT","stat":"network","delta":2},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.03,"quarters":2,"label":"동네 호감 방문객 +3%"}]'::jsonb, '[]'::jsonb, '행사 날 아이들이 손편지를 들고 왔습니다. 동네 엄마들 사이에 소문이 났습니다.', '-' FROM turning_points WHERE code = 'MI_DONATION_ASK';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '음료 정도만 보내기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"아동센터 음료 후원"},{"type":"STAT","stat":"network","delta":1}]'::jsonb, '[]'::jsonb, '부담 없는 선에서 마음을 보탰습니다. 선생님이 고맙다고 전화를 주셨습니다.', '-' FROM turning_points WHERE code = 'MI_DONATION_ASK';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '이번엔 사정을 말하고 거절', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"network","delta":-1}]'::jsonb, '[]'::jsonb, '지금은 여유가 없다고 솔직히 말씀드렸습니다. 마음 한구석이 조금 무겁습니다.', '-' FROM turning_points WHERE code = 'MI_DONATION_ASK';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_CREDIT_TAB', '단골의 외상 부탁', '3년째 드나들던 단골손님이 요즘 일이 끊겨 사정이 어렵다며 한 달만 외상을 달아 달라고 합니다. 이번 달 먹을 것까지 합치면 80만 원 정도가 될 것 같습니다.', '{"all":[{"var":"serviceCode","op":"in","value":["CS100001","CS100002","CS100007","CS100009"]},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.5, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '장부 열고 외상 허락', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"단골 외상 미수금"},{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_CREDIT_OPEN","value":true}]'::jsonb, '[]'::jsonb, '공책 한 권을 꺼내 첫 장에 이름을 적었습니다. 손님이 몇 번이고 고맙다고 했습니다.', '-' FROM turning_points WHERE code = 'MI_CREDIT_TAB';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '절반만 외상, 나머진 다음에', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"단골 외상 미수금"},{"type":"FLAG","flag":"MI_F_CREDIT_OPEN","value":true}]'::jsonb, '[]'::jsonb, '선을 정해 두고 외상을 받았습니다. 손님도 그 정도면 충분하다며 웃었습니다.', '-' FROM turning_points WHERE code = 'MI_CREDIT_TAB';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '외상은 안 된다고 거절', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"network","delta":-2},{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '원칙을 지켰습니다. 그 뒤로 그 손님 얼굴을 보기가 어려워졌습니다.', '-' FROM turning_points WHERE code = 'MI_CREDIT_TAB';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_CREDIT_RETURN', '외상 장부의 결말', '외상을 달아 두었던 단골손님 소식이 들립니다. 새 일자리를 구했다는 말도 있고, 이사를 갔다는 말도 있습니다. 장부 속 이름을 보며 어떻게 할지 정해야 합니다.', '{"all":[{"var":"flag.MI_F_CREDIT_OPEN","op":"==","value":true},{"var":"history.quartersSince.MI_CREDIT_TAB","op":"between","value":[2,6]}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 0, 1, 1, 80, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '조심스럽게 연락해 보기', '{"base":0.6,"statBonus":[{"stat":"network","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":1000000,"memo":"외상값과 감사 인사"},{"type":"STAT","stat":"network","delta":2},{"type":"FLAG","flag":"MI_F_CREDIT_OPEN","value":false}]'::jsonb, '[{"type":"STAT","stat":"network","delta":-1},{"type":"FLAG","flag":"MI_F_CREDIT_OPEN","value":false}]'::jsonb, '손님이 봉투를 들고 찾아왔습니다. 외상값에 조금 더 얹어 "그때 정말 고마웠다"고 했습니다.', '번호가 바뀌어 있었습니다. 장부 속 이름에 조용히 줄을 그었습니다.' FROM turning_points WHERE code = 'MI_CREDIT_RETURN';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '알아서 오길 기다리기', '{"base":0.45,"statBonus":[{"stat":"service","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":1200000,"memo":"외상값과 회식 예약"},{"type":"STAT","stat":"network","delta":1},{"type":"FLAG","flag":"MI_F_CREDIT_OPEN","value":false}]'::jsonb, '[{"type":"FLAG","flag":"MI_F_CREDIT_OPEN","value":false}]'::jsonb, '어느 저녁, 그 손님이 동료들을 데리고 와 외상값을 갚고 회식까지 하고 갔습니다.', '기다렸지만 끝내 연락이 없었습니다. 외상값은 수업료로 치기로 했습니다.' FROM turning_points WHERE code = 'MI_CREDIT_RETURN';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '장부를 덮고 잊어버리기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":1},{"type":"STAT","stat":"service","delta":1},{"type":"FLAG","flag":"MI_F_CREDIT_OPEN","value":false}]'::jsonb, '[]'::jsonb, '받을 돈 생각에 마음 쓰지 않기로 했습니다. 오히려 홀가분합니다.', '-' FROM turning_points WHERE code = 'MI_CREDIT_RETURN';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_EQUIPMENT_BREAK', '주방 기계가 멈췄다', '한창 바쁜 점심에 주력 기계에서 이상한 소리가 나더니 멈춰 버렸습니다. 정식 수리는 비싸고 오래 걸리며, 중고 부품은 싸지만 언제 또 말썽일지 모릅니다.', '{"var":"quartersOperated","op":">=","value":3}'::jsonb, 0.5, '[]'::jsonb, 0, 1, 6, 2, 2, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '제조사 정식 수리', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-2000000,"memo":"주방 기계 정식 수리비"},{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '사흘 만에 기계가 새것처럼 돌아왔습니다. 수리비는 아팠지만 마음은 편합니다.', '-' FROM turning_points WHERE code = 'MI_EQUIPMENT_BREAK';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '중고 부품으로 빠르게 수리', '{"base":0.55,"statBonus":[{"stat":"management","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"중고 부품 수리비"}]'::jsonb, '[{"type":"CASH","amount":-1800000,"memo":"중고 부품 재수리비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.96,"quarters":1,"label":"메뉴 품절 방문객 -4%"}]'::jsonb, '당일 저녁부터 다시 돌아갔습니다. 싸고 빠르게 해결했습니다.', '고친 지 2주 만에 또 멈췄습니다. 결국 정식 수리까지 받아야 했습니다.' FROM turning_points WHERE code = 'MI_EQUIPMENT_BREAK';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '영상 보며 직접 고쳐 보기', '{"base":0.3,"statBonus":[{"stat":"cooking","per10":0.03},{"stat":"stamina","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"공구와 부품 구입"},{"type":"STAT","stat":"management","delta":2}]'::jsonb, '[{"type":"CASH","amount":-2500000,"memo":"고장 악화 후 수리비"},{"type":"STAT","stat":"stamina","delta":-2}]'::jsonb, '밤새 영상을 돌려 본 끝에 기계가 다시 돌았습니다. 사장님 손재주에 직원들이 박수를 쳤습니다.', '나사 하나를 잘못 풀어 일이 커졌습니다. 기사님이 "손대지 마시지…"라며 한숨을 쉬었습니다.' FROM turning_points WHERE code = 'MI_EQUIPMENT_BREAK';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_SOLO_DINERS', '혼자 오는 점심 손님', '점심마다 혼자 오는 직장인이 부쩍 늘었습니다. 4인 테이블에 한 명씩 앉다 보니 자리가 금방 차고, 일행 손님은 문 앞에서 돌아섭니다. 자리 배치를 손볼 때가 된 것 같습니다.', '{"all":[{"var":"serviceCode","op":"in","value":["CS100001","CS100002","CS100003","CS100004","CS100006","CS100008"]},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.5, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '창가에 1인 바 좌석 만들기', '{"base":0.6,"statBonus":[{"stat":"management","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-2000000,"memo":"1인 좌석 공사비"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.06,"quarters":3,"label":"좌석 회전 개선 매출 +6%"}]'::jsonb, '[{"type":"CASH","amount":-2000000,"memo":"1인 좌석 공사비"},{"type":"STAT","stat":"service","delta":-1}]'::jsonb, '혼밥 손님은 창가로, 일행 손님은 테이블로. 점심 회전이 확 빨라졌습니다.', '좌석이 좁다는 불평이 나왔습니다. 공사비만큼의 효과는 아직입니다.' FROM turning_points WHERE code = 'MI_SOLO_DINERS';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '합석을 정중히 안내', '{"base":0.4,"statBonus":[{"stat":"service","per10":0.06}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.03,"quarters":1,"label":"합석 회전 매출 +3%"}]'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":1,"label":"합석 불편 방문객 -5%"}]'::jsonb, '처음엔 어색해하던 손님들이 금세 익숙해졌습니다. 점심 대기가 줄었습니다.', '"밥은 편하게 먹고 싶다"는 손님들이 다른 가게로 옮겨 갔습니다.' FROM turning_points WHERE code = 'MI_SOLO_DINERS';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '지금 배치 유지', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.97,"quarters":1,"label":"점심 자리 부족 방문객 -3%"}]'::jsonb, '[]'::jsonb, '바뀐 것은 없습니다. 점심마다 몇 팀은 그냥 돌아갑니다.', '-' FROM turning_points WHERE code = 'MI_SOLO_DINERS';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_PRICE_GRUMBLE', '"요즘 좀 비싸졌네요"', '계산하던 단골손님이 웃으며 "요즘 여기 좀 비싸졌네요"라고 한마디 던졌습니다. 농담처럼 들렸지만, 메뉴판 가격이 동네 평균보다 높은 건 사실입니다.', '{"all":[{"var":"priceLevel","op":"==","value":"HIGH"},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '가격 그대로, 양을 넉넉히', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"푸짐한 양 방문객 +5%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"양 늘리기 원가 +2%p"}]'::jsonb, '[]'::jsonb, '접시가 묵직해지자 "이 가격이면 납득"이라는 말이 나왔습니다.', '-' FROM turning_points WHERE code = 'MI_PRICE_GRUMBLE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '점심 세트로 가격 부담 낮추기', '{"base":0.55,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.04,"quarters":2,"label":"점심 세트 매출 +4%"}]'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.01,"quarters":2,"label":"세트 구성 원가 +1%p"},{"type":"STAT","stat":"marketing","delta":-1}]'::jsonb, '세트 메뉴를 내놓자 가격 이야기가 쏙 들어갔습니다.', '세트가 단품 매출만 갉아먹었습니다. 계산해 보니 남는 게 줄었습니다.' FROM turning_points WHERE code = 'MI_PRICE_GRUMBLE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '재료 이야기로 설득하기', '{"base":0.5,"statBonus":[{"stat":"cooking","per10":0.04},{"stat":"service","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"STAT","stat":"service","delta":2}]'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":2,"label":"비싸다는 인식 방문객 -5%"}]'::jsonb, '재료를 어디서 어떻게 가져오는지 들은 손님이 "그래서 맛있구나"라며 끄덕였습니다.', '변명처럼 들렸는지 "비싼 집"이라는 꼬리표가 붙었습니다.' FROM turning_points WHERE code = 'MI_PRICE_GRUMBLE';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_PRICE_DOUBT', '"너무 싼데 괜찮은 거예요?"', '동네 게시판에 "가격이 너무 싸서 재료가 걱정된다"는 글이 올라왔습니다. 싸게 팔아 손님을 모았는데 오히려 그게 의심을 사고 있습니다. 억울하지만 해명이 필요해 보입니다.', '{"all":[{"var":"priceLevel","op":"==","value":"LOW"},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.6, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '재료 원산지와 주방을 공개', '{"base":0.7,"statBonus":[{"stat":"marketing","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"주방 공개 사진 촬영"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"투명한 주방 신뢰 +5%"}]'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"주방 공개 사진 촬영"}]'::jsonb, '깨끗한 주방 사진에 "싼데 깔끔하다"는 댓글이 줄줄이 달렸습니다.', '사진을 올렸지만 글은 이미 묻혀 버려 별 반응이 없었습니다.' FROM turning_points WHERE code = 'MI_PRICE_DOUBT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '가격을 조금 올리기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.04,"quarters":2,"label":"가격 현실화 매출 +4%"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.97,"quarters":2,"label":"가격 인상 방문객 -3%"}]'::jsonb, '[]'::jsonb, '가격을 올리자 오히려 "이제 좀 믿음이 간다"는 반응이 나왔습니다. 손님은 조금 줄었습니다.', '-' FROM turning_points WHERE code = 'MI_PRICE_DOUBT';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '신경 쓰지 않기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.97,"quarters":1,"label":"재료 의심 방문객 -3%"}]'::jsonb, '[]'::jsonb, '글은 며칠 뒤 사라졌지만 그사이 몇몇 손님은 발길을 끊었습니다.', '-' FROM turning_points WHERE code = 'MI_PRICE_DOUBT';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_CASH_CRUNCH', '아슬아슬한 통장 잔고', '통장 잔고를 보다 한숨이 나왔습니다. 마침 거래 은행에서 소상공인 운영자금 대출 안내 문자가 왔고, 창고에는 아직 팔 만한 재고와 안 쓰는 집기도 조금 있습니다.', '{"all":[{"var":"cash","op":"<","value":10000000},{"var":"quartersOperated","op":">=","value":2}]}'::jsonb, 0.8, '[]'::jsonb, 0, 1, 4, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '소액 운영자금 대출 받기', '{"base":0.7,"statBonus":[{"stat":"management","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":5000000,"memo":"소상공인 운영자금 대출"},{"type":"MODIFIER","target":"rent","mode":"ADD","value":400000,"quarters":3,"label":"대출 이자 상환 +40만 원"}]'::jsonb, '[{"type":"CASH","amount":2000000,"memo":"소상공인 운영자금 대출(감액)"},{"type":"MODIFIER","target":"rent","mode":"ADD","value":200000,"quarters":3,"label":"대출 이자 상환 +20만 원"}]'::jsonb, '서류를 챙겨 간 덕에 심사가 빨리 끝났습니다. 숨통이 조금 트였습니다.', '심사에서 한도가 깎였습니다. 그래도 급한 불은 껐습니다.' FROM turning_points WHERE code = 'MI_CASH_CRUNCH';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '재고 할인 판매와 집기 정리', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":2000000,"memo":"재고 할인 판매·집기 매각"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":0.96,"quarters":1,"label":"할인 판매 매출 -4%"}]'::jsonb, '[]'::jsonb, '안 쓰던 냉장고와 남은 재고를 정리했습니다. 가게가 조금 휑해졌습니다.', '-' FROM turning_points WHERE code = 'MI_CASH_CRUNCH';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '사장님 몫을 줄여 버티기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":1500000,"memo":"사장님 생활비 절감"},{"type":"STAT","stat":"stamina","delta":-3}]'::jsonb, '[]'::jsonb, '한동안 사장님 밥은 가게 남은 반찬입니다. 그래도 직원 월급은 지켰습니다.', '-' FROM turning_points WHERE code = 'MI_CASH_CRUNCH';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_RENOVATION_PITCH', '인테리어 업체의 리뉴얼 견적', '장사가 자리를 잡아 가자 인테리어 업체가 부분 리뉴얼 견적서를 들고 왔습니다. 조명과 벽면만 바꿔도 분위기가 확 달라진다는데, 견적서 맨 아래 숫자가 만만치 않습니다.', '{"all":[{"var":"cash","op":">=","value":40000000},{"var":"quartersOperated","op":">=","value":3}]}'::jsonb, 0.4, '[]'::jsonb, 0, 1, 8, 1, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '조명과 벽면 리뉴얼', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-5000000,"memo":"매장 부분 리뉴얼"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.1,"quarters":3,"label":"리뉴얼 매장 방문객 +10%"}]'::jsonb, '[{"type":"CASH","amount":-5000000,"memo":"매장 부분 리뉴얼"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.03,"quarters":1,"label":"리뉴얼 매장 방문객 +3%"}]'::jsonb, '새 조명 아래 음식 사진이 잘 나온다며 손님들이 휴대폰을 꺼내 듭니다.', '돈을 들인 것치고는 손님들이 달라진 걸 잘 모르는 눈치입니다.' FROM turning_points WHERE code = 'MI_RENOVATION_PITCH';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '간판만 새로 달기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"간판 교체"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.04,"quarters":2,"label":"새 간판 방문객 +4%"}]'::jsonb, '[]'::jsonb, '밤에도 잘 보이는 간판 덕에 지나가던 사람들이 한 번씩 고개를 돌립니다.', '-' FROM turning_points WHERE code = 'MI_RENOVATION_PITCH';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '다음에 하겠다고 돌려보내기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '견적서는 서랍에 넣어 두었습니다. 지금은 현금이 더 든든합니다.', '-' FROM turning_points WHERE code = 'MI_RENOVATION_PITCH';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MI_WINTER_MENU', '찬바람과 겨울 메뉴', '찬바람이 불기 시작하자 손님들이 따뜻한 메뉴부터 찾습니다. 겨울 한정 메뉴를 내면 계절 손님을 잡을 수 있지만, 재료를 새로 들이고 손에 익히는 데 품이 듭니다.', '{"var":"quarterOfYear","op":"==","value":3}'::jsonb, 0.9, '[]'::jsonb, 0, 1, 3, 2, 1, 50, true, 'MINOR', 'STORY');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '겨울 한정 메뉴 출시', '{"base":0.6,"statBonus":[{"stat":"cooking","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"겨울 메뉴 개발·재료비"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.06,"quarters":1,"label":"겨울 한정 메뉴 매출 +6%"}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"겨울 메뉴 개발·재료비"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.01,"quarters":1,"label":"남은 겨울 재료 원가 +1%p"}]'::jsonb, '김이 모락모락 나는 새 메뉴가 첫눈 오는 날 불티나게 팔렸습니다.', '맛은 괜찮았지만 손님들은 늘 먹던 메뉴만 시켰습니다.' FROM turning_points WHERE code = 'MI_WINTER_MENU';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '따뜻한 음료 서비스만', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-500000,"memo":"따뜻한 음료 서비스"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.02,"quarters":1,"label":"따뜻한 서비스 방문객 +2%"}]'::jsonb, '[]'::jsonb, '들어오는 손님마다 따뜻한 차 한 잔을 건넸습니다. 작은 정성이 통했습니다.', '-' FROM turning_points WHERE code = 'MI_WINTER_MENU';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '메뉴는 그대로', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":1}]'::jsonb, '[]'::jsonb, '계절이 바뀌어도 늘 같은 맛. 그것도 우리 가게의 장점입니다.', '-' FROM turning_points WHERE code = 'MI_WINTER_MENU';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_SALES_SLUMP', '업종 매출 하락', '{area.quarterLabel} 실제 집계에서 이 상권 {serviceName} 매출이 직전 분기 대비 {area.salesChangePct}%로 뒷걸음질했습니다. 이 하락은 이미 이번 분기 결산에 반영됐습니다. 이제 대응을 정할 차례입니다.', '{"var":"area.salesChangePct","op":"<=","value":-10}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '가격 인하 프로모션', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.08,"quarters":2,"label":"가격 인하 방문객 +8%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"가격 인하 원가 +2%p"}]'::jsonb, '[{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"가격 인하 원가 +2%p"}]'::jsonb, '동네 전체가 주춤한 사이, 가격을 낮춘 우리 가게로 손님이 몰렸습니다.', '가격을 내렸지만 다들 지갑을 닫은 분위기라 마진만 줄었습니다.' FROM turning_points WHERE code = 'MD_SALES_SLUMP';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '메뉴 정비로 내실 다지기', '{"base":0.55,"statBonus":[{"stat":"cooking","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"메뉴 정비 비용"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"메뉴 정비 매출 +5%"}]'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"메뉴 정비 비용"},{"type":"STAT","stat":"cooking","delta":1}]'::jsonb, '안 팔리는 메뉴를 덜어 내고 잘 팔리는 메뉴에 힘을 줬습니다. 객단가가 올랐습니다.', '메뉴판은 깔끔해졌지만 매출로 이어지기엔 시간이 더 필요해 보입니다.' FROM turning_points WHERE code = 'MD_SALES_SLUMP';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '버티기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"management","delta":1},{"type":"STAT","stat":"stamina","delta":-1}]'::jsonb, '[]'::jsonb, '흐름이 바뀌길 기다리기로 했습니다. 상권 하락분은 이미 결산에 들어 있어 추가 손실은 없습니다.', '-' FROM turning_points WHERE code = 'MD_SALES_SLUMP';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_SALES_BOOM', '업종 매출 상승', '{area.quarterLabel} 실제 집계에서 이 상권 {serviceName} 매출이 직전 분기 대비 {area.salesChangePct}% 늘었습니다. 이 상승은 이미 이번 분기 결산에 반영됐습니다. 흐름을 탈지 지켜볼지 정해야 합니다.', '{"var":"area.salesChangePct","op":">=","value":15}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '영업시간 늘려 손님 더 받기', '{"base":0.65,"statBonus":[{"stat":"stamina","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"호황기 연장 영업 매출 +5%"},{"type":"STAT","stat":"stamina","delta":-2}]'::jsonb, '[{"type":"STAT","stat":"stamina","delta":-3}]'::jsonb, '늦게까지 불을 켜 두자 퇴근길 손님이 꾸준히 들어왔습니다.', '문은 오래 열었지만 손님은 평소 시간에만 몰렸습니다. 피로만 쌓였습니다.' FROM turning_points WHERE code = 'MD_SALES_BOOM';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '가격을 살짝 올리기', '{"base":0.5,"statBonus":[{"stat":"marketing","per10":0.04},{"stat":"cooking","per10":0.03}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"가격 조정 매출 +5%"}]'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":1,"label":"가격 인상 반감 방문객 -5%"}]'::jsonb, '분위기 좋은 시기라 손님들이 가격 조정을 크게 신경 쓰지 않았습니다.', '하필 우리 가게만 올린 모양새가 되어 손님이 잠깐 줄었습니다.' FROM turning_points WHERE code = 'MD_SALES_BOOM';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '현상 유지', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '들뜨지 않고 하던 대로 하기로 했습니다. 상권 상승분은 이미 결산에 들어 있습니다.', '-' FROM turning_points WHERE code = 'MD_SALES_BOOM';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_NEW_RIVALS', '같은 업종 개업', '{area.quarterLabel} 이 상권에서 같은 업종 가게가 새로 문을 열었습니다(개업 {area.openings}곳). 실제 기록입니다. 새 가게 개업 효과에 손님을 빼앗기지 않으려면 대응이 필요해 보입니다.', '{"var":"area.openings","op":">=","value":2}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '우리 가게만의 강점 알리기', '{"base":0.55,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"차별화 홍보비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.06,"quarters":2,"label":"차별화 홍보 방문객 +6%"}]'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"차별화 홍보비"}]'::jsonb, '"원조는 여기"라는 말이 돌면서 새 가게 구경을 마친 손님들이 돌아왔습니다.', '홍보물을 돌렸지만 다들 새 가게 구경에 바빴습니다.' FROM turning_points WHERE code = 'MD_NEW_RIVALS';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '단골 감사 이벤트', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"단골 감사 이벤트"},{"type":"STAT","stat":"service","delta":2},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.03,"quarters":1,"label":"단골 이벤트 방문객 +3%"}]'::jsonb, '[]'::jsonb, '오래 찾아 준 손님들께 작은 선물을 드렸습니다. 단골들이 든든히 자리를 지켜 줍니다.', '-' FROM turning_points WHERE code = 'MD_NEW_RIVALS';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '신경 쓰지 않기', '{"base":0.5,"statBonus":[{"stat":"cooking","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"STAT","stat":"cooking","delta":1}]'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":1,"label":"신규 경쟁점 이탈 방문객 -5%"}]'::jsonb, '새 가게 소식에 흔들리지 않고 맛에 집중했습니다. 손님은 결국 맛을 따라왔습니다.', '새 가게 개업 할인에 손님 몇이 넘어갔습니다.' FROM turning_points WHERE code = 'MD_NEW_RIVALS';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_CLOSING_WAVE', '같은 업종 폐업', '{area.quarterLabel} 이 상권에서 같은 업종 가게 여럿이 문을 닫았습니다(폐업 {area.closings}곳). 실제 기록입니다. 남은 가게에겐 기회일 수도, 경고일 수도 있습니다.', '{"var":"area.closings","op":">=","value":2}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '문 닫은 가게 손님 맞이하기', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"신규 손님 맞이 홍보"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.07,"quarters":2,"label":"폐업 가게 손님 흡수 +7%"}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"신규 손님 맞이 홍보"}]'::jsonb, '단골 가게를 잃은 손님들이 하나둘 우리 가게 문을 열었습니다.', '홍보를 했지만 손님들은 아예 다른 업종으로 발길을 돌린 듯합니다.' FROM turning_points WHERE code = 'MD_CLOSING_WAVE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '폐업 매장 집기 싸게 인수', '{"base":0.6,"statBonus":[{"stat":"management","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"중고 집기 인수"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":-0.02,"quarters":3,"label":"효율 좋은 설비 원가 -2%p"}]'::jsonb, '[{"type":"CASH","amount":-1500000,"memo":"중고 집기 인수"}]'::jsonb, '쓸 만한 설비를 헐값에 들였습니다. 주방이 한결 효율적으로 돌아갑니다.', '받아 온 집기 상태가 생각보다 나빠 창고에 넣어 두었습니다.' FROM turning_points WHERE code = 'MD_CLOSING_WAVE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '지출을 줄이며 몸 사리기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":1000000,"memo":"지출 절감"},{"type":"STAT","stat":"marketing","delta":-1}]'::jsonb, '[]'::jsonb, '불필요한 지출을 줄였습니다. 폐업 소식이 남 일 같지 않습니다.', '-' FROM turning_points WHERE code = 'MD_CLOSING_WAVE';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_FOOT_TRAFFIC_UP', '유동인구 증가', '{area.quarterLabel} 실제 집계에서 이 상권 유동인구가 직전 분기 대비 {area.floatingPopChangePct}% 늘었습니다. 늘어난 발길은 이미 결산에 반영됐습니다. 이 손님들을 붙잡을 방법을 골라야 합니다.', '{"var":"area.floatingPopChangePct","op":">=","value":8}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '영업시간 연장', '{"base":0.65,"statBonus":[{"stat":"stamina","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"연장 영업 매출 +5%"},{"type":"STAT","stat":"stamina","delta":-2}]'::jsonb, '[{"type":"STAT","stat":"stamina","delta":-3}]'::jsonb, '저녁 늦게까지 골목을 오가는 사람들이 불 켜진 우리 가게로 들어왔습니다.', '늘어난 사람들은 대부분 그냥 지나가는 길이었습니다.' FROM turning_points WHERE code = 'MD_FOOT_TRAFFIC_UP';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '피크 시간 단기 인력 추가', '{"base":0.6,"statBonus":[{"stat":"management","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"단기 인력 인건비"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.06,"quarters":2,"label":"피크 응대 개선 방문객 +6%"}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"단기 인력 인건비"}]'::jsonb, '대기 줄이 짧아지자 지나가던 사람들도 부담 없이 들어왔습니다.', '인력을 늘렸지만 손님은 생각만큼 늘지 않았습니다.' FROM turning_points WHERE code = 'MD_FOOT_TRAFFIC_UP';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '현상 유지', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":1}]'::jsonb, '[]'::jsonb, '늘어난 유동인구 효과는 이미 결산에 들어 있습니다. 무리하지 않기로 했습니다.', '-' FROM turning_points WHERE code = 'MD_FOOT_TRAFFIC_UP';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_FOOT_TRAFFIC_DOWN', '유동인구 감소', '{area.quarterLabel} 실제 집계에서 이 상권 유동인구가 직전 분기 대비 {area.floatingPopChangePct}%로 줄었습니다. 감소분은 이미 결산에 반영됐습니다. 줄어든 발길을 어떻게 메울지 정해야 합니다.', '{"var":"area.floatingPopChangePct","op":"<=","value":-8}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '포장·배달 비중 늘리기', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"포장 용기·홍보비"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"포장 주문 매출 +5%"}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"포장 용기·홍보비"}]'::jsonb, '골목은 한산해도 포장 주문 알림은 꾸준히 울렸습니다.', '용기를 잔뜩 사 두었는데 포장 주문은 드문드문했습니다.' FROM turning_points WHERE code = 'MD_FOOT_TRAFFIC_DOWN';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '남은 동네 단골에 집중', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"service","delta":2},{"type":"STAT","stat":"network","delta":1}]'::jsonb, '[]'::jsonb, '찾아오는 손님 한 명 한 명에게 더 정성을 쏟았습니다.', '-' FROM turning_points WHERE code = 'MD_FOOT_TRAFFIC_DOWN';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '고정비 줄이기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":1000000,"memo":"운영비 절감"},{"type":"STAT","stat":"service","delta":-1}]'::jsonb, '[]'::jsonb, '전기와 소모품을 아끼고 재료 주문을 줄였습니다. 대신 매장 분위기가 조금 가라앉았습니다.', '-' FROM turning_points WHERE code = 'MD_FOOT_TRAFFIC_DOWN';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_FRANCHISE_ENTRY', '프랜차이즈 진입', '{area.quarterLabel} 실제 집계에서 이 상권 {serviceName} 업종의 프랜차이즈 점포가 늘었습니다. 간판 큰 가게 옆에서 동네 가게가 살아남는 방법을 고민할 때입니다.', '{"var":"area.franchiseChange","op":">=","value":1}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '동네 가게다운 정 강조하기', '{"base":0.6,"statBonus":[{"stat":"service","per10":0.04},{"stat":"marketing","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"단골 소통 이벤트"},{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.05,"quarters":2,"label":"동네 가게 호감 방문객 +5%"}]'::jsonb, '[{"type":"CASH","amount":-800000,"memo":"단골 소통 이벤트"}]'::jsonb, '"여기 사장님은 내 이름을 안다"는 단골들이 큰 간판 대신 우리 가게를 택했습니다.', '정성은 들였지만 새 프랜차이즈의 할인 공세가 더 셌습니다.' FROM turning_points WHERE code = 'MD_FRANCHISE_ENTRY';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '가격으로 맞대응', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":1.04,"quarters":2,"label":"가격 맞대응 방문객 +4%"},{"type":"MODIFIER","target":"costRate","mode":"ADD","value":0.02,"quarters":2,"label":"가격 맞대응 원가 +2%p"}]'::jsonb, '[]'::jsonb, '가격표를 맞추자 손님은 지켰지만 남는 돈은 줄었습니다.', '-' FROM turning_points WHERE code = 'MD_FRANCHISE_ENTRY';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '지켜보기', '{"base":0.5,"statBonus":[{"stat":"cooking","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.95,"quarters":1,"label":"프랜차이즈 개점 효과 방문객 -5%"}]'::jsonb, '개점 열기가 식자 손님들이 익숙한 우리 가게로 돌아왔습니다.', '개점 행사에 손님 몇이 넘어갔습니다.' FROM turning_points WHERE code = 'MD_FRANCHISE_ENTRY';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_FEWER_STORES', '줄어든 가게, 늘어난 매출', '{area.quarterLabel} 이 상권 같은 업종 점포 수 증감은 {area.storeChange}곳인데, 매출은 직전 분기 대비 {area.salesChangePct}%를 기록했습니다. 실제 기록이며 이미 결산에 반영됐습니다. 남은 가게들 몫이 커진 셈입니다.', '{"all":[{"var":"area.storeChange","op":"<=","value":-1},{"var":"area.salesChangePct","op":">","value":0}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '메뉴를 늘려 손님 더 받기', '{"base":0.5,"statBonus":[{"stat":"cooking","per10":0.05}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"신메뉴 준비 비용"},{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.06,"quarters":2,"label":"메뉴 확대 매출 +6%"}]'::jsonb, '[{"type":"CASH","amount":-1000000,"memo":"신메뉴 준비 비용"},{"type":"STAT","stat":"stamina","delta":-1}]'::jsonb, '사라진 가게의 메뉴를 찾던 손님들이 우리 가게 신메뉴에 정착했습니다.', '메뉴만 늘고 주방은 더 바빠졌습니다. 손님은 원래 먹던 것만 찾았습니다.' FROM turning_points WHERE code = 'MD_FEWER_STORES';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '가격을 제값으로 정리', '{"base":0.6,"statBonus":[{"stat":"marketing","per10":0.04}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"revenue","mode":"MULTIPLY","value":1.04,"quarters":2,"label":"가격 정상화 매출 +4%"}]'::jsonb, '[{"type":"MODIFIER","target":"visitors","mode":"MULTIPLY","value":0.96,"quarters":1,"label":"가격 정상화 방문객 -4%"}]'::jsonb, '경쟁이 줄어든 덕에 가격을 정리해도 손님이 그대로였습니다.', '조금 서둘렀습니다. 손님 몇이 가격표 앞에서 망설였습니다.' FROM turning_points WHERE code = 'MD_FEWER_STORES';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '하던 대로', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '좋은 흐름을 그대로 두기로 했습니다. 상권 변화는 이미 결산에 들어 있습니다.', '-' FROM turning_points WHERE code = 'MD_FEWER_STORES';
INSERT INTO turning_points (code, title, description, condition_expr, base_probability, stat_bonus, prob_min, prob_max, cooldown_quarters, max_fires, min_turn, priority, enabled, tier, source) VALUES ('MD_HIGH_CLOSING_RATE', '높은 폐업률과 빈 점포', '{area.quarterLabel} 실제 집계에서 이 상권 같은 업종 폐업률이 높게 나왔습니다(폐업 {area.closings}곳). 골목에 빈 점포가 늘자 건물주들도 세입자 눈치를 보기 시작했다는 이야기가 들립니다.', '{"all":[{"var":"area.closingRatePct","op":">=","value":10},{"var":"area.closings","op":">=","value":1}]}'::jsonb, 1, '[]'::jsonb, 0, 1, 4, 1, 1, 50, true, 'MINOR', 'DATA');
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 1, '건물주와 임대료 재협상', '{"base":0.45,"statBonus":[{"stat":"network","per10":0.06}],"min":0.1,"max":0.9}'::jsonb, '[{"type":"MODIFIER","target":"rent","mode":"ADD","value":-500000,"quarters":3,"label":"임대료 재협상 -50만 원"},{"type":"STAT","stat":"network","delta":1}]'::jsonb, '[{"type":"STAT","stat":"network","delta":-1}]'::jsonb, '빈 점포가 늘어난 사정을 아는 건물주가 한발 물러섰습니다.', '건물주는 "우리 건물은 다르다"며 협상을 받아 주지 않았습니다.' FROM turning_points WHERE code = 'MD_HIGH_CLOSING_RATE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 2, '비상금 따로 모아 두기', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"CASH","amount":800000,"memo":"운영비 절감 비상금"},{"type":"STAT","stat":"marketing","delta":-1}]'::jsonb, '[]'::jsonb, '홍보비를 줄여 비상금을 마련했습니다. 당분간은 조용히 버팁니다.', '-' FROM turning_points WHERE code = 'MD_HIGH_CLOSING_RATE';
INSERT INTO turning_point_options (turning_point_id, order_no, label, success_formula, on_success, on_fail, success_text, fail_text) SELECT id, 3, '흔들리지 않고 영업', '{"base":1,"min":1,"max":1}'::jsonb, '[{"type":"STAT","stat":"stamina","delta":-1},{"type":"STAT","stat":"management","delta":1}]'::jsonb, '[]'::jsonb, '주변이 흔들려도 우리 가게 문은 제시간에 열었습니다. 폐업 흐름은 이미 결산에 들어 있습니다.', '-' FROM turning_points WHERE code = 'MD_HIGH_CLOSING_RATE';
